#!/usr/bin/env node
/**
 * A contract id is generated by task_define and cannot be derived from the
 * goal. When the model passed a guessed id, `task_acceptance` answered "not
 * found — check task ids with the define output" — a dead end once the define
 * output has fallen out of context (compaction). The ids it can use are named
 * in the refusal.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { taskAcceptanceTool, taskDefineTool } from '../dist/tools/task-tools.js';

function ctx(workspaceDir) {
  return {
    workspaceDir,
    sessionKey: 'task-acceptance-unknown-id',
    abortSignal: new AbortController().signal,
    taskContracts: 'allow',
  };
}

async function workspace(t) {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'moss-acceptance-id-'));
  t.after(() => fs.rm(dir, { recursive: true, force: true }));
  return dir;
}

async function defineTask(dir, goal) {
  const out = await taskDefineTool.execute(
    { goal, acceptance_criteria: [{ metric: 'http_status', expected: '200' }] },
    ctx(dir)
  );
  const taskId = out.match(/Task contract (task_\S+)/)?.[1];
  assert.ok(taskId, `task id not found in: ${out}`);
  return taskId;
}

test('an unknown contract id is refused with the ids that exist', async (t) => {
  const dir = await workspace(t);
  const taskId = await defineTask(dir, 'serve a page on port 9090');
  const out = await taskAcceptanceTool.execute({ task_id: 'serve-a-page-on-port-9090' }, ctx(dir));
  assert.match(out, /^Error: task_acceptance: no contract with id serve-a-page-on-port-9090/);
  assert.match(out, /Nothing was evaluated/);
  assert.match(out, new RegExp(`- ${taskId} \\[active\\] serve a page on port 9090`));
});

test('omitting task_id still evaluates the latest contract', async (t) => {
  const dir = await workspace(t);
  await defineTask(dir, 'serve a page on port 9090');
  const out = await taskAcceptanceTool.execute({}, ctx(dir));
  assert.match(out, /^Task acceptance /);
});

test('no contracts at all points at task_define', async (t) => {
  const dir = await workspace(t);
  const out = await taskAcceptanceTool.execute({}, ctx(dir));
  assert.match(out, /^Error: task_acceptance: no task contracts in this workspace/);
});
